+func embeddedSchema(t *testing.T, gvKey string) []byte {
+	t.Helper()
+	paths, err := openapitest.NewEmbeddedFileClient().Paths()
+	if err != nil {
+		t.Fatal(err)
+	}
+	gv, ok := paths[gvKey]
+	if !ok {
+		t.Fatalf("no embedded test schema for %q", gvKey)
+	}
+	data, err := gv.Schema("application/json")
+	if err != nil {
+		t.Fatal(err)
+	}
+	return data
+}
