+			}
+
+			tt.run(sched, tt.oldObj, tt.newObj)
+
+			if len(observed) != 2 {
+				t.Fatalf("expected exactly 2 queueing hints (Delete, Add), got %d: %#v", len(observed), observed)
+			}
+			if observed[0].action != fwk.Delete {
